// The Windows APIs that KGames uses, generated by windows-bindgen from the
// names in BindingsGenerator/Filters.txt. Every crate in the repo that calls
// Windows uses these bindings, so that a type like HWND or ID3D12Device is
// the same type in all of them.

#[path = "Bindings.rs"]
#[allow(
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    dead_code,
    clippy::all
)]
mod bindings;

pub use bindings::*;

// Win32 functions report failure with a null handle and set the thread's last error.
pub fn check_handle(handle: *mut core::ffi::c_void) -> windows_core::Result<()> {
    if handle.is_null() {
        Err(windows_core::Error::from_thread())
    } else {
        Ok(())
    }
}
